async (page) => { const context = page.context(); let collector = null; for (const candidate of context.pages()) { const flag = await candidate.evaluate(() => window.__isCollector === true).catch(() => false); if (flag) { collector = candidate; break; } } if (!collector) return { error: 'collector tab not found' }; const worker = context.pages().find((candidate) => candidate !== collector) || await context.newPage(); await worker.setViewportSize({ width: 1000, height: 1000 }); const jobs = await collector.evaluate(() => window.__jobs || []); await collector.evaluate(() => { window.__dumps = window.__dumps || []; }); const results = []; for (const job of jobs) { const result = { name: job.name }; try { const postUrl = `https://t.me/${job.channel}/${job.post}?embed=1&mode=tme`; await worker.goto(postUrl, { waitUntil: 'load', timeout: 60000 }); await worker.waitForTimeout(1200); const postDump = await worker.evaluate(async (extra) => { extra.tgPost = window.__tg.extractPost(); return window.__ac.dump(extra); }, { name: job.name + '_post', status: 200, requested: postUrl }); await collector.evaluate((item) => { window.__dumps.push(item); }, postDump); const post = postDump.extra.tgPost; result.post = post.post ? { author: post.post.author, date: post.post.datetime, views: post.post.views, text: post.post.text.slice(0, 120), media: post.post.media.map((item) => item.type).join(',') } : null; result.postError = post.error; result.replies = post.repliesText; if (job.shotBase) await worker.screenshot({ path: job.shotBase + '_post.png', fullPage: true }); const discussionUrl = `https://t.me/${job.channel}/${job.post}?embed=1&discussion=1&comments_limit=100`; await worker.goto(discussionUrl, { waitUntil: 'load', timeout: 60000 }); await worker.waitForTimeout(1500); result.expand = await worker.evaluate(async () => window.__tg.expand(120)); const discussionDump = await worker.evaluate(async (extra) => { extra.tgDiscussion = window.__tg.extractDiscussion(); return window.__ac.dump(extra); }, { name: job.name + '_discussion', status: 200, requested: discussionUrl }); await collector.evaluate((item) => { window.__dumps.push(item); }, discussionDump); const discussion = discussionDump.extra.tgDiscussion; result.header = discussion.header; result.discussionError = discussion.error; result.comments = discussion.comments.length; result.moreLeft = discussion.moreLeft; result.moreState = discussion.moreState; result.body = discussion.comments.length ? '' : discussion.bodyText; result.heads = discussion.comments.map((comment) => `${comment.id} | ${comment.author} | ${comment.datetime} | ${comment.text.slice(0, 100).replace(/\s+/g, ' ')}${comment.media.length ? ' | медиа: ' + comment.media.map((item) => item.type).join(',') : ''}`).slice(0, job.heads || 60); if (job.shotBase) { await worker.evaluate(() => window.scrollTo(0, 0)); await worker.screenshot({ path: job.shotBase + '_discussion.png', fullPage: true }); } } catch (error) { result.error = String(error).slice(0, 400); } results.push(result); } return results; }
